// ==UserScript==
// @name         Wells Fargo Offer Lite
// @namespace    https://github.com/yangzichao/card-offer-hub
// @version      1.0.0
// @description  Manually scan and activate eligible account-wide Wells Fargo Deals with conservative serial pacing
// @author       Zichao Yang
// @match        https://web.secure.wellsfargo.com/auth/deals-portal*
// @match        https://web.secure.wellsfargo.com/deals-portal/*
// @grant        GM_getValue
// @grant        GM_setValue
// @noframes
// @run-at       document-idle
// @homepageURL  https://github.com/yangzichao/card-offer-hub/tree/main/issuers/wellsfargo/wellsfargo-offer-lite
// @supportURL   https://github.com/yangzichao/card-offer-hub/issues
// @updateURL    https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/wellsfargo-offer-lite.user.js
// @downloadURL  https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/wellsfargo-offer-lite.user.js
// ==/UserScript==
// Generated from issuers/wellsfargo/wellsfargo-offer-lite/src by "npm run build". Do not edit this file.
// Installing from https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/wellsfargo-offer-lite.user.js lets Tampermonkey update it on its own.

(function () {
    'use strict';

    // Source: core/state.js
    const SETTINGS = {
        id: "wellsfargo-offer-lite", name: "Wells Fargo Offer Lite", version: "1.0.0",
        retrievePath: '/deals-portal/as/getDeals', enrollmentPath: '/deals-portal/as/activateCLDeal',
        gapMilliseconds: 500, timeoutMilliseconds: 45000, defaultCooldownMilliseconds: 300000
    };
    const state = {
        offers: [], accountConsent: false, busy: false, stopRequested: false, needsScan: true,
        nextRequestAt: 0, cooldownUntil: 0, storageError: '',
        status: 'Open My Wells Fargo Deals and click Scan offers. Nothing runs automatically.',
        confirmed: 0, completed: 0, total: 0, panel: null, collapsed: false, search: ''
    };
    function updateStatus(message) {
        state.status = message;
        renderPanel();
    }
    function ensureRunning() {
        if (state.stopRequested) throw new Error('Stopped. Scan again before adding more offers.');
        if (location.origin !== 'https://web.secure.wellsfargo.com'
            || !/^\/(?:auth\/deals-portal(?:\/|$)|deals-portal\/)/.test(location.pathname)) {
            throw new Error('Open the signed-in My Wells Fargo Deals page and scan again.');
        }
    }
    function stopRun() {
        state.stopRequested = true;
        updateStatus('Stopping after the current request settles. Its result may still be confirmed.');
    }

    // Source: core/storage.js
    // Store only pacing state. Account IDs, offers, cookies, and request headers stay
    // in memory; a reload always requires a fresh scan and manual account consent.
    function restorePacing() {
        try {
            const saved = GM_getValue(`${SETTINGS.id}:pacing`, null);
            if (saved === null) return;
            if (saved.schemaVersion !== 1 || !Number.isFinite(saved.cooldownUntil)
                || !Number.isFinite(saved.nextRequestAt)) {
                throw new Error('Unsupported pacing snapshot; stored data was preserved.');
            }
            state.cooldownUntil = Math.max(state.cooldownUntil, saved.cooldownUntil);
            state.nextRequestAt = Math.max(state.nextRequestAt, saved.nextRequestAt);
        } catch {
            state.storageError = 'Cannot read pacing storage. Resolve Tampermonkey storage before running.';
        }
    }
    function savePacing() {
        try {
            GM_setValue(`${SETTINGS.id}:pacing`, {
                schemaVersion: 1, cooldownUntil: state.cooldownUntil, nextRequestAt: state.nextRequestAt
            });
        } catch {
            state.storageError = 'Cannot save pacing storage. Further requests are blocked; reload after fixing storage.';
            renderPanel();
        }
    }

    // Source: api/session.js
    function activationUrl() {
        // The signed-in HTML embeds window.initialState = JSON.parse("...").
        // Parse only the JSON literal; never evaluate page code or copy a HAR token.
        const candidates = [];
        for (const script of document.querySelectorAll('script:not([src])')) {
            const match = script.textContent.match(/\bwindow\.initialState\s*=\s*JSON\.parse\(\s*("(?:\\.|[^"\\])*")\s*\)/);
            if (!match) continue;
            try {
                const initialState = JSON.parse(JSON.parse(match[1]));
                const action = initialState?.metadata?.clDealsActivateAction;
                if (typeof action === 'string') candidates.push(action);
            } catch { /* An unfamiliar bootstrap is not an activation authorization. */ }
        }
        if (candidates.length !== 1) throw new Error('Activation session is unavailable. Reopen My Wells Fargo Deals, then scan again.');
        let url;
        try { url = new URL(candidates[0], location.origin); }
        catch { throw new Error('Activation session URL was not recognized. Reopen My Wells Fargo Deals.'); }
        if (url.origin !== location.origin || url.pathname !== SETTINGS.enrollmentPath
            || url.username || url.password || url.hash
            || [...url.searchParams.keys()].some(key => key !== 'token')
            || url.searchParams.getAll('token').length !== 1 || !url.searchParams.get('token')?.trim()) {
            throw new Error('Activation session URL was not recognized. Reopen My Wells Fargo Deals.');
        }
        return url.pathname + url.search;
    }

    // Source: api/transport.js
    function retryAfterMilliseconds(value, now = Date.now()) {
        if (typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value.trim())) return Number(value) * 1000;
        const deadline = typeof value === 'string' ? Date.parse(value) : NaN;
        return Number.isFinite(deadline) ? Math.max(0, deadline - now) : SETTINGS.defaultCooldownMilliseconds;
    }
    async function waitForRequestSlot() {
        while (Date.now() < state.nextRequestAt) {
            ensureRunning();
            await new Promise(resolve => setTimeout(resolve, Math.min(250, state.nextRequestAt - Date.now())));
        }
        ensureRunning();
        if (state.storageError) throw new Error(state.storageError);
        if (Date.now() < state.cooldownUntil) {
            throw new Error(`Rate limited. Try a new scan after ${new Date(state.cooldownUntil).toLocaleTimeString()}.`);
        }
    }
    async function requestJson(path, body) {
        if (![SETTINGS.retrievePath, SETTINGS.enrollmentPath].includes(path)) throw new Error('Unsupported Wells Fargo endpoint.');
        await waitForRequestSlot();
        const enrollment = path === SETTINGS.enrollmentPath;
        const url = enrollment ? activationUrl() : path;
        const headers = { Accept: 'application/json' };
        if (enrollment) headers['Content-Type'] = 'application/json';
        // Reserve a slot before sending. A reload or closed tab releases Web Locks,
        // but must not permit a new tab to immediately overlap this pending request.
        state.nextRequestAt = Date.now() + SETTINGS.timeoutMilliseconds + SETTINGS.gapMilliseconds;
        savePacing();
        if (state.storageError) throw new Error(state.storageError);
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), SETTINGS.timeoutMilliseconds);
        try {
            const response = await fetch(url, {
                method: enrollment ? 'POST' : 'GET', credentials: 'same-origin', redirect: 'error', cache: 'no-store',
                headers, ...(enrollment ? { body: JSON.stringify(body) } : {}), signal: controller.signal
            });
            if (response.status === 429) {
                state.cooldownUntil = Math.max(state.cooldownUntil,
                    Date.now() + retryAfterMilliseconds(response.headers.get('Retry-After')));
            }
            // Include body consumption in the response-completion pacing boundary.
            const responseText = await response.text();
            if (response.status === 429) throw new Error('Wells Fargo returned HTTP 429. Cooling down; scan again later.');
            if (!response.ok) throw new Error(`Wells Fargo returned HTTP ${response.status}. Scan again after resolving the error.`);
            let payload;
            try { payload = JSON.parse(responseText); }
            catch { throw new Error('Wells Fargo returned a non-JSON response. Sign in and scan again.'); }
            return payload;
        } catch (error) {
            // Do not display browser errors that could contain URLs or session data.
            if (error.name === 'AbortError') throw new Error('Request timed out; result is unconfirmed. Scan again.');
            if (error instanceof TypeError) throw new Error('Network request failed; result is unconfirmed. Scan again.');
            throw error;
        } finally {
            clearTimeout(timeout);
            state.nextRequestAt = Date.now() + SETTINGS.gapMilliseconds;
            savePacing();
        }
    }

    // Source: api/contracts.js
    function normalizeOffers(payload) {
        if (payload?.status?.statusCode !== 200
            || payload.status.messages?.[0]?.code !== 'SUCCESS' || typeof payload.data !== 'string') {
            throw new Error('Wells Fargo did not confirm a successful offer scan. Reopen Deals and scan again.');
        }
        let data;
        try { data = JSON.parse(payload.data); }
        catch { throw new Error('Wells Fargo offer data was not recognized.'); }
        const available = data?.availableDeals;
        if (data?.error || !Array.isArray(available?.cardlyticsEligibleDeals) || !Array.isArray(available?.activatedDeals)) {
            throw new Error('Wells Fargo offer-list response was not recognized.');
        }
        const offers = new Map();
        for (const [records, activatedGroup] of [[available.cardlyticsEligibleDeals, false], [available.activatedDeals, true]]) {
            for (const record of records) {
                const details = record?.merchantDealDetails;
                if (typeof details?.merchantOfferId !== 'string' || !/^\d+$/.test(details.merchantOfferId)
                    || typeof details.status !== 'string') throw new Error('Wells Fargo returned an incomplete offer record.');
                const supported = record.vendorName === 'CL' && record.multiCardFlag === false
                    && (details.cards === undefined || (Array.isArray(details.cards) && details.cards.length === 0));
                let status = 'UNSUPPORTED';
                if (activatedGroup || record.isActivated === true) status = 'ACTIVATED';
                else if (supported && record.isActivated === false && details.status === 'AVAILABLE') status = 'AVAILABLE';
                const offer = {
                    offerId: details.merchantOfferId, status,
                    merchant: typeof details.merchantName === 'string' ? details.merchantName : 'Merchant',
                    title: typeof details.shortDescription === 'string' ? details.shortDescription : '',
                    expires: typeof details.expirationDate === 'string' ? details.expirationDate : ''
                };
                const existing = offers.get(offer.offerId);
                if (existing) {
                    if (existing.status !== status) existing.status = 'CONFLICT';
                } else offers.set(offer.offerId, offer);
            }
        }
        // The captured count is 0 despite 78 records. Use the actual arrays.
        return [...offers.values()];
    }
    function enrollmentBody(offer) {
        if (offer.status !== 'AVAILABLE' || !/^\d+$/.test(offer.offerId)) throw new Error('Offer is not eligible for activation. Scan again.');
        // Captured successful activations send an empty value, NOT the list checkSum.
        return { offerIdCheckSumMap: { [offer.offerId]: '' }, activityCode: 'ENROLL', displayType: 'Offer', sendEmailFlag: false };
    }
    function enrollmentConfirmed(payload) {
        return payload?.status === 'SUCCESS';
    }

    // Source: workflows/runner.js
    async function runExclusive(action) {
        if (state.busy) return;
        state.busy = true;
        state.stopRequested = false;
        renderPanel();
        const execute = async () => {
            restorePacing();
            if (state.storageError) throw new Error(state.storageError);
            ensureRunning();
            await action();
        };
        try {
            // Prevent two tabs running this script from enrolling simultaneously.
            if (!navigator.locks?.request) throw new Error('This browser does not support the required tab lock. Use current Chrome.');
            await navigator.locks.request(SETTINGS.id, { ifAvailable: true }, async lock => {
                if (!lock) throw new Error(`${SETTINGS.name} is running in another tab. Wait for it to finish.`);
                await execute();
            });
        } catch (error) {
            state.needsScan = true;
            updateStatus(error.message);
        } finally {
            state.busy = false;
            renderPanel();
        }
    }

    // Source: workflows/offers.js
    async function scanCurrentAccount() {
        state.needsScan = true;
        state.offers = [];
        state.confirmed = 0;
        state.completed = 0;
        state.total = 0;
        updateStatus('Scanning current account offers…');
        const payload = await requestJson(SETTINGS.retrievePath);
        ensureRunning();
        state.offers = normalizeOffers(payload);
        state.needsScan = false;
        renderPanel();
    }
    function scanOffers() {
        return runExclusive(async () => {
            await scanCurrentAccount();
            updateStatus(`Scan complete: ${state.offers.filter(offer => offer.status === 'AVAILABLE').length} eligible offers. Confirm the account scope before adding.`);
        });
    }
    function addAllOffers() {
        if (!state.accountConsent || state.needsScan) return;
        return runExclusive(async () => {
            // Check the current page token before any activation, then refresh the list.
            activationUrl();
            await scanCurrentAccount();
            const queue = state.offers.filter(offer => offer.status === 'AVAILABLE');
            state.total = queue.length;
            for (const offer of queue) {
                ensureRunning();
                updateStatus(`Activating ${state.completed + 1}/${state.total}: ${offer.merchant}. Waiting for the next request slot…`);
                try {
                    const payload = await requestJson(SETTINGS.enrollmentPath, enrollmentBody(offer));
                    if (!enrollmentConfirmed(payload)) throw new Error('Activation was not explicitly confirmed. Scan again before continuing.');
                    offer.status = 'ACTIVATED';
                    state.confirmed++;
                    state.completed++;
                    renderPanel();
                } catch (error) {
                    offer.status = 'UNCONFIRMED';
                    throw error;
                }
            }
            ensureRunning();
            updateStatus(`Finished: ${state.confirmed}/${state.total} confirmed. Refresh the Wells Fargo page to update its deal badges.`);
        });
    }

    // Source: ui/styles.js
    const PANEL_STYLES = `
    :host{all:initial;position:fixed;bottom:18px;right:18px;z-index:2147483646;font:13px/1.5 system-ui,sans-serif;color:#253247}
    *{box-sizing:border-box} .panel{width:min(440px,calc(100vw - 24px));max-height:85vh;overflow:auto;background:white;border:1px solid #d7dfe8;border-radius:12px;box-shadow:0 10px 36px #19304926}
    header,section,footer{padding:12px 16px} header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e5eaf0} h2{font-size:16px;margin:0}p{margin:6px 0}
    button,input{font:inherit}button{padding:7px 10px;border:1px solid #c7d2df;border-radius:6px;background:#f7f9fc;color:#253247;cursor:pointer}button.primary{background:#1763a6;color:white;border-color:#1763a6}button:disabled{opacity:.45;cursor:not-allowed}
    .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.muted{color:#637185;font-size:12px}.cards{max-height:160px;overflow:auto}.card{display:flex;gap:8px;padding:6px 0}.card input{flex:none}
    input[type=search]{width:100%;padding:8px;border:1px solid #c7d2df;border-radius:6px}.offers{max-height:190px;overflow:auto}.offer{padding:8px 0;border-bottom:1px solid #e5eaf0;overflow-wrap:anywhere}.offer small{display:block;color:#637185}
    footer{background:#f6f8fb;overflow-wrap:anywhere}.error{color:#a13030}[hidden]{display:none!important}
    `;

    // Source: ui/panel.js
    function mountPanel() {
        if (document.getElementById(SETTINGS.id)) return;
        const host = document.createElement('div');
        host.id = SETTINGS.id;
        const panel = host.attachShadow({ mode: 'open' });
        panel.innerHTML = `<style>${PANEL_STYLES}</style><div class="panel">
          <header><h2></h2><button id="collapse" aria-label="Minimize Wells Fargo panel">−</button></header>
          <div id="body"><section>
            <p class="muted">Scan My Wells Fargo Deals, then activate eligible offers. About 4 offers/minute. No automatic retries.</p>
            <label class="card"><input id="consent" type="checkbox" aria-label="Allow account-wide Wells Fargo activation">Activate eligible offers for this signed-in account.</label>
            <p class="muted">This API has no per-card selection. Offers requiring a card choice are skipped.</p>
            <div class="actions"><button id="scan" aria-label="Scan Wells Fargo offers">Scan offers</button>
            <button id="add" class="primary" aria-label="Scan and add all Wells Fargo offers">Scan & add all</button>
            <button id="stop" aria-label="Stop Wells Fargo activation">Stop</button></div>
            <p class="muted">Search only filters the display; all eligible account offers are processed.</p>
          </section><section><p id="counts"></p><input id="search" type="search" aria-label="Search Wells Fargo offers" placeholder="Search merchants">
          <div id="offers" class="offers"></div></section>
          <footer><div id="status" role="status" aria-live="polite"></div><div id="storage-error" class="error" role="alert"></div></footer></div></div>`;
        panel.querySelector('h2').textContent = `${SETTINGS.name} ${SETTINGS.version}`;
        panel.getElementById('scan').addEventListener('click', scanOffers);
        panel.getElementById('add').addEventListener('click', addAllOffers);
        panel.getElementById('stop').addEventListener('click', stopRun);
        panel.getElementById('consent').addEventListener('change', event => {
            if (state.busy) return;
            state.accountConsent = event.target.checked;
            renderPanel();
        });
        panel.getElementById('search').addEventListener('input', event => { state.search = event.target.value; renderOffers(); });
        panel.getElementById('collapse').addEventListener('click', () => {
            state.collapsed = !state.collapsed;
            panel.getElementById('body').hidden = state.collapsed;
            panel.getElementById('collapse').textContent = state.collapsed ? '+' : '−';
            panel.getElementById('collapse').setAttribute('aria-label', state.collapsed ? 'Expand Wells Fargo panel' : 'Minimize Wells Fargo panel');
        });
        document.body.appendChild(host);
        state.panel = panel;
        renderPanel();
    }

    // Source: ui/render.js
    function renderOffers() {
        if (!state.panel) return;
        const container = state.panel.getElementById('offers');
        container.replaceChildren();
        const search = state.search.trim().toLowerCase();
        const visible = state.offers.filter(offer => `${offer.merchant} ${offer.title}`.toLowerCase().includes(search));
        for (const offer of visible.slice(0, 200)) {
            const row = document.createElement('div');
            row.className = 'offer';
            const title = document.createElement('strong');
            title.textContent = `${offer.merchant} · ${offer.title}`;
            const detail = document.createElement('small');
            detail.textContent = `${offer.status} · ${offer.expires}`;
            row.append(title, detail);
            container.appendChild(row);
        }
        if (visible.length > 200) {
            const note = document.createElement('p');
            note.textContent = `Showing 200 of ${visible.length}; search to narrow the display. All eligible offers remain in the queue.`;
            container.appendChild(note);
        }
    }
    function renderPanel() {
        if (!state.panel) return;
        const panel = state.panel;
        const blocked = state.busy || Boolean(state.storageError);
        panel.getElementById('scan').disabled = blocked;
        panel.getElementById('add').disabled = blocked || !state.accountConsent || state.needsScan;
        panel.getElementById('consent').disabled = blocked;
        panel.getElementById('consent').checked = state.accountConsent;
        panel.getElementById('stop').disabled = !state.busy || state.stopRequested;
        panel.getElementById('status').textContent = state.status;
        panel.getElementById('storage-error').textContent = state.storageError;
        panel.getElementById('counts').textContent = `${state.offers.length} offers · ${state.offers.filter(offer => offer.status === 'AVAILABLE').length} eligible · ${state.offers.filter(offer => ['UNSUPPORTED', 'CONFLICT'].includes(offer.status)).length} skipped · ${state.confirmed}/${state.total} added this run`;
        renderOffers();
    }

    // Source: initialize.js
    // --- Init ---
    restorePacing();
    mountPanel();
})();
